1. AES encryption and decryption in Python:
```
import hashlib
from Crypto.Cipher import AES
from Crypto import Random

def aes_encryption(key, data):
    cipher = AES.new(key, AES.MODE_ECB)
    return cipher.encrypt(data)

def aes_decryption(key, data):
    cipher = AES.new(key, AES.MODE_ECB)
    return cipher.decrypt(data)
```
2. RSA encryption and decryption in Python:
```
import rsa

def rsa_encryption(public_key, data):
    encrypted_data = rsa.encrypt(data, public_key)
    return encrypted_data

def rsa_decryption(private_key, encrypted_data):
    decrypted_data = rsa.decrypt(encrypted_data, private_key)
    return decrypted_data
```
3. AES encryption and decryption in Java:
```java
import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import java.security.Key;

public class AesEncryption {
    private static final String ALGORITHM = "AES";
    private static final byte[] keyValue = new byte[] { 'T', 'h', 'e', 'B', 'e','s', 't', 'S', 'e', 'c', 'r', 'e', 't', 'K', 'e', 'y' };

    public static void main(String[] args) throws Exception {
        String data = "The quick brown fox jumps over the lazy dog";
        Key key = new SecretKeySpec(keyValue, ALGORITHM);
        Cipher cipher = Cipher.getInstance(ALGORITHM);
        cipher.init(Cipher.ENCRYPT_MODE, key);
        byte[] encrypted = cipher.doFinal(data.getBytes());
        System.out.println("Encrypted: " + new String(encrypted));

        cipher.init(Cipher.DECRYPT_MODE, key);
        byte[] decrypted = cipher.doFinal(encrypted);
        System.out.println("Decrypted: " + new String(decrypted));
    }
}
```
